import argparse
import json
from pathlib import Path
import sys
import tempfile
from . import TeamPlanner

ACTIONS = {'member': 'add_member', 'activity': 'create_activity', 'enroll': 'enroll', 'enroll-batch': 'enroll_batch', 'preview-enroll': 'preview_enrollments', 'cancel': 'cancel_enrollments', 'transfer': 'transfer_enrollment', 'transfer-batch': 'transfer_enrollments', 'preview-transfer': 'preview_transfer_enrollments', 'split-activity': 'split_activity', 'reschedule': 'reschedule_activity', 'reschedule-batch': 'reschedule_activities', 'preview-reschedule': 'preview_reschedule_activities', 'roster': 'roster', 'list': 'activities', 'complete': 'record_completion', 'complete-batch': 'record_completions', 'correct-completions': 'correct_completions', 'completions': 'completions', 'merge': 'merge_member', 'merge-activities': 'merge_activities', 'schedule': 'member_schedule', 'enrollment-options': 'enrollment_options', 'training-progress': 'training_progress', 'training-requirements': 'training_requirements', 'training-validity': 'training_validity', 'training-timeline': 'training_validity_timeline', 'training-coverage': 'training_coverage', 'training-alerts': 'training_alerts', 'renewal-options': 'training_renewal_options', 'export-schedule': 'export_schedule'}

def samples(name):
    return json.loads((Path(__file__).resolve().parent.parent / "examples" / name).read_text(encoding="utf-8"))

def demo(app):
    for member in samples("members.json"):
        app.add_member(**member)
    app.create_activity(**samples("activity.json"))
    app.enroll(**samples("enrollment.json"))
    # 2026-10-15 的虚构安排：A-002 与 A-001 同日，由小陈和小周报满；
    # 小陈在 A-003 已登记完成，报名仍然保留，当天原本互为冲突。
    app.create_activity("A-002", "安全规范", "2026-10-15", 2)
    app.create_activity("A-003", "团队协作", "2026-10-15", 2)
    app.enroll("A-002", "M-001")
    app.enroll("A-002", "M-003")
    app.enroll("A-003", "M-001")
    app.record_completion("A-003", "M-001", "2026-10-15")
    # 一次取消两场，标识带首尾空白也会先去除；满员的 A-002 释放席位，
    # 返回顺序与输入一致，且各活动只移除小陈本人。
    cancelled = app.cancel_enrollments("M-001", [" A-002 ", "A-001"])
    if [a["activity_id"] for a in cancelled] != ["A-002", "A-001"]:
        raise ValueError("demo: cancelled activities must follow the input order")
    if cancelled[0]["participants"] != ["M-003"] or cancelled[1]["participants"] != []:
        raise ValueError("demo: only the cancelling member is removed")
    # 取消后小陈只剩已完成的 A-003，同日冲突随之消失。
    schedule = app.member_schedule("M-001")
    if [r["activity_id"] for r in schedule] != ["A-003"] or schedule[0]["conflict_activity_ids"] != []:
        raise ValueError("demo: same-day conflicts must disappear after cancellation")
    # 释放的席位立即可用：小林报进原本满员的 A-002，小陈重新报回 A-001。
    app.enroll("A-002", "M-002")
    app.enroll("A-001", "M-001")
    # 小陈在 A-003 已有本人完成记录：整次取消被拒绝，两边名单均不变，
    # 完成记录继续保留。
    try:
        app.cancel_enrollments("M-001", ["A-001", "A-003"])
    except ValueError:
        pass
    else:
        raise ValueError("demo: cancelling a completed activity must fail")
    if [m["member_id"] for m in app.roster("A-001")["members"]] != ["M-001"]:
        raise ValueError("demo: rosters must stay unchanged after a rejected cancellation")
    if [m["member_id"] for m in app.roster("A-003")["members"]] != ["M-001"]:
        raise ValueError("demo: the completed activity roster must stay unchanged")
    if [r["activity_id"] for r in app.completions("M-001")] != ["A-003"]:
        raise ValueError("demo: completion records must be kept")
    # 整组完成登记：2026-10-15 当天两场虚构培训（小陈的 A-001、小周的 A-002）
    # 一次性提交，允许跨活动、跨成员，标识带首尾空白会先去除；返回顺序与输入
    # 一致，字段与单条 complete 相同，两场都应登记成功。
    recorded = app.record_completions([
        {"activity_id": " A-001 ", "member_id": "M-001", "completed_on": "2026-10-15"},
        {"activity_id": "A-002", "member_id": " M-003 ", "completed_on": "2026-10-15"},
    ])
    if [r["activity_id"] for r in recorded] != ["A-001", "A-002"]:
        raise ValueError("demo: batch records must follow the input order")
    if recorded[0] != {"activity_id": "A-001", "member_id": "M-001", "completed_on": "2026-10-15", "title": "新成员产品介绍", "on": "2026-10-15"}:
        raise ValueError("demo: batch record fields must match the single complete result")
    # 末条失败（小陈在 A-003 已有完成记录）时整组拒绝：首条小林在 A-002 的
    # 新记录也不得写入，数据文件字节不变。
    before = app.path.read_bytes()
    try:
        app.record_completions([
            {"activity_id": "A-002", "member_id": "M-002", "completed_on": "2026-10-15"},
            {"activity_id": "A-003", "member_id": "M-001", "completed_on": "2026-10-15"},
        ])
    except ValueError:
        pass
    else:
        raise ValueError("demo: a batch with a failing last record must be rejected")
    if before != app.path.read_bytes():
        raise ValueError("demo: a rejected batch must leave data.json bytes unchanged")
    if app.completions("M-002") != []:
        raise ValueError("demo: no record from the rejected batch may survive")
    # 完成登记不取消报名：两场新完成的培训仍然占位、名单顺序不变。
    if [m["member_id"] for m in app.roster("A-001")["members"]] != ["M-001"]:
        raise ValueError("demo: completion keeps the enrollment")
    return app.roster("A-001")

def main(argv=None):
    parser = argparse.ArgumentParser(description="团队培训安排")
    parser.add_argument("--root", required=True, help="local data directory")
    parser.add_argument("action", choices=[*ACTIONS, "demo"])
    parser.add_argument("input", nargs="?", help="UTF-8 JSON object, or array of objects, containing API arguments")
    args = parser.parse_args(argv)
    try:
        if args.action == "demo":
            # Sample operations run in a fresh child directory and never overwrite user's data.
            Path(args.root).mkdir(parents=True, exist_ok=True)
            with tempfile.TemporaryDirectory(prefix="sample-", dir=args.root) as location:
                value = demo(TeamPlanner(location))
        else:
            payload = json.loads(Path(args.input).read_text(encoding="utf-8")) if args.input else {}
            app = TeamPlanner(args.root)
            method = getattr(app, ACTIONS[args.action])
            if isinstance(payload, list):
                value = []
                for row in payload:
                    if not isinstance(row, dict):
                        raise ValueError("each input must be an object")
                    value.append(method(**row))
            elif isinstance(payload, dict):
                value = method(**payload)
            else:
                raise ValueError("input must be an object or array")
        print(json.dumps(value, ensure_ascii=False, sort_keys=True))
        return 0
    except (ValueError, KeyError, TypeError, OSError) as error:
        print(json.dumps({"error": str(error)}, ensure_ascii=False), file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

from pathlib import Path
import json
import os
import tempfile
from datetime import date

COLLECTIONS = ("members", "activities", "completions")

class JsonStore:
    def __init__(self, root):
        self.root = Path(root)
        self.path = self.root / "data.json"

    def _read(self):
        # A missing file is an empty history. Any other filesystem problem
        # (permissions, data.json being a directory, ...) stays an OSError.
        try:
            raw = self.path.read_bytes()
        except FileNotFoundError:
            return {}
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise ValueError("data.json must be a valid UTF-8 file")
        try:
            value = json.loads(text)
        except json.JSONDecodeError:
            raise ValueError("data.json must be valid JSON")
        if not isinstance(value, dict):
            raise ValueError("stored document must be an object")
        # The whole history is validated on every read, so a query can never
        # hide an unrelated broken record behind its filters.
        validate_document(value)
        return value

    def _write(self, value):
        # Validate before touching the filesystem: invalid data never creates
        # a missing directory or file and never replaces an existing file.
        validate_document(value)
        self.root.mkdir(parents=True, exist_ok=True)
        fd, name = tempfile.mkstemp(prefix=".data-", suffix=".json", dir=self.root)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as stream:
                json.dump(value, stream, ensure_ascii=False, sort_keys=True, indent=2)
                stream.write("\n")
            os.replace(name, self.path)
        finally:
            if os.path.exists(name):
                os.unlink(name)

def text(value, label):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(label + " must be a nonempty string")
    return value.strip()

def identifier(value, label):
    # Stored keys and participant ids are matched exactly, never trimmed:
    # surrounding whitespace or an empty string are invalid on disk.
    if not isinstance(value, str) or not value or value != value.strip():
        raise ValueError(label + " must be a nonempty string without surrounding whitespace")
    return value

def positive(value, label):
    if type(value) is not int or value <= 0:
        raise ValueError(label + " must be a positive integer")
    return value

def day(value, label):
    # Only a real YYYY-MM-DD calendar date is accepted: no other types,
    # no surrounding whitespace, no relaxed parsing.
    if not isinstance(value, str) or len(value) != 10 or value[4] != "-" or value[7] != "-":
        raise ValueError(label + " must be a YYYY-MM-DD date string")
    try:
        parsed = date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except (ValueError, OverflowError):
        raise ValueError(label + " must be a real YYYY-MM-DD date")
    if parsed.isoformat() != value:
        raise ValueError(label + " must be a real YYYY-MM-DD date")
    return parsed.isoformat()

def validate_document(data):
    # Business consistency check for a whole historical document. Missing
    # collections are empty; present ones must be JSON objects (null is not an
    # empty object). Extra fields on the document, members and activities are
    # allowed and left untouched by the caller.
    if not isinstance(data, dict):
        raise ValueError("stored document must be an object")
    for name in COLLECTIONS:
        if name in data and not isinstance(data[name], dict):
            raise ValueError(name + " must be an object")
    members = data.get("members", {})
    activities = data.get("activities", {})
    completions = data.get("completions", {})

    for key, member in members.items():
        identifier(key, "member key")
        if not isinstance(member, dict):
            raise ValueError("member entry must be an object")
        if not isinstance(member.get("member_id"), str) or member["member_id"] != key:
            raise ValueError("member_id must match the member object key")
        if not isinstance(member.get("name"), str) or not member["name"].strip():
            raise ValueError("member name must be a nonblank string")

    activity_dates = {}
    for key, activity in activities.items():
        identifier(key, "activity key")
        if not isinstance(activity, dict):
            raise ValueError("activity entry must be an object")
        if not isinstance(activity.get("activity_id"), str) or activity["activity_id"] != key:
            raise ValueError("activity_id must match the activity object key")
        if not isinstance(activity.get("title"), str) or not activity["title"].strip():
            raise ValueError("activity title must be a nonblank string")
        activity_dates[key] = day(activity.get("on"), "on")
        positive(activity.get("capacity"), "capacity")
        participants = activity.get("participants")
        if not isinstance(participants, list):
            raise ValueError("participants must be an array")
        seen = set()
        for member_id in participants:
            identifier(member_id, "participant id")
            if member_id in seen:
                raise ValueError("participants must not contain duplicate member ids")
            if member_id not in members:
                raise ValueError("participant references an unknown member")
            seen.add(member_id)
        if len(participants) > activity["capacity"]:
            raise ValueError("participant count must not exceed capacity")

    for activity_id, done in completions.items():
        identifier(activity_id, "completion activity key")
        if not isinstance(done, dict):
            raise ValueError("completion records must be an object")
        if activity_id not in activities:
            raise ValueError("completion references an unknown activity")
        enrolled = set(activities[activity_id]["participants"])
        for member_id, completed_on in done.items():
            identifier(member_id, "completion member id")
            if member_id not in enrolled:
                raise ValueError("completion references a member not enrolled in the activity")
            completed_on = day(completed_on, "completed_on")
            if date.fromisoformat(completed_on) < date.fromisoformat(activity_dates[activity_id]):
                raise ValueError("completed_on must be on or after the activity date")

